--
-- Estructura de tabla para la tabla `person`
--

CREATE TABLE `person` (
  `id` int(10) UNSIGNED NOT NULL,
  `lastname` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `firstname` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `bussinesname` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `nombres` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `apellidopaterno` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `apellidomaterno` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dni` char(8) COLLATE utf8_unicode_ci DEFAULT NULL,
  `ruc` char(11) COLLATE utf8_unicode_ci DEFAULT NULL,
  `direccion` varchar(120) COLLATE utf8_unicode_ci DEFAULT NULL,
  `telefono` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email` varchar(30) COLLATE utf8_unicode_ci DEFAULT NULL,
  `autorizado` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `solicitado` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `workertype_id` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `updated_at` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `fechanacimiento` date DEFAULT NULL,
  `anotaciones` varchar(1000) COLLATE utf8_unicode_ci DEFAULT NULL,
  `sexo` char(1) COLLATE utf8_unicode_ci DEFAULT NULL,
  `modalidad_id` int(11) DEFAULT NULL,
  `dscto` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `rest` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

